(()=>{let cases=[],data,index=0;const root=document.getElementById('researchContent');
const words={en:{heading:'Compare the recordings.',sub:'Two research cases, with their recorded ultrasound findings.',present:'Stenosis documented',absent:'No stenosis documented',finding:'Dataset ultrasound finding',residual:'Residual diameter',reference:'Reference diameter',case:'Case',notes:'Different participants · same sensor location · not a before/after comparison.',traces:'Recorded signal',listen:'Listen',download:'Download recording',freq:'Time–frequency view',raw:'ECG and sensor traces',source:'Source & recording notes',metrics:'Audio features',centroid:'Spectral centroid',dominant:'Dominant frequency bin',duration:'Duration',rate:'Sampling rate',simple:'A regular-looking waveform does not rule out stenosis. The case labels come from the dataset’s examination, not an app diagnosis.',loading:'Loading recordings…',error:'Unable to load recordings. Please reload.',open:'Compare research recordings ↗',annotation:'FiSaV · ultrasound-annotated cases',sensor:'PZT1 · anastomosis',fft:'Relative spectral power · 0–1,500 Hz',rawNote:'Each trace has its own vertical range in original sensor units.',processed:'Audio is filtered and amplified for listening. Levels are not directly comparable across patients.',sourceLink:'FiSaV dataset',paper:'Publication',license:'CC BY 4.0'},ar:{heading:'قارن التسجيلات.',sub:'حالتان بحثيتان مع نتائج الفحص المسجّلة.',present:'تضيّق موثّق',absent:'لا تضيّق موثّق',finding:'نتيجة فحص الموجات فوق الصوتية في البيانات',residual:'القطر المتبقي',reference:'القطر المرجعي',case:'الحالة',notes:'مشاركان مختلفان · نفس موضع الحساس · ليست مقارنة قبل وبعد.',traces:'الإشارة المسجّلة',listen:'استمع',download:'تنزيل التسجيل',freq:'عرض الزمن والتردد',raw:'إشارات ECG والحساسات',source:'المصدر وملاحظات التسجيل',metrics:'خصائص الصوت',centroid:'مركز الطيف',dominant:'التردد الغالب',duration:'المدة',rate:'معدل العينات',simple:'انتظام شكل الموجة لا ينفي التضيّق. تصنيف الحالة مأخوذ من فحص البيانات، وليس تشخيصًا من التطبيق.',loading:'تحميل التسجيلات…',error:'تعذّر تحميل التسجيلات. أعد تحميل الصفحة.',open:'قارن التسجيلات البحثية ↗',annotation:'FiSaV · حالات موثّقة بالفحص',sensor:'PZT1 · موضع اتصال الشريان والوريد',fft:'قدرة طيفية نسبية · من 0 إلى 1,500 Hz',rawNote:'لكل إشارة مدى عمودي مستقل بوحدات الحساس الأصلية.',processed:'الصوت مرشّح ومكبّر للاستماع. المستويات غير قابلة للمقارنة المباشرة بين المرضى.',sourceLink:'بيانات FiSaV',paper:'الورقة البحثية',license:'CC BY 4.0'}};
const tr=k=>words[document.documentElement.lang==='ar'?'ar':'en'][k];
function node(tag,cls,value){const e=document.createElement(tag);if(cls)e.className=cls;if(value!==undefined)e.textContent=value;return e;}
function render(){const cta=document.getElementById('researchCta');if(cta)cta.textContent=tr('open');root.replaceChildren();if(!cases.length){root.append(node('p','empty',tr('loading')));return;}root.append(node('span','badge teal',tr('annotation')),node('h2','comparison-heading',tr('heading')),node('p','research-intro',tr('sub')),node('p','comparison-caption',tr('notes')));
const grid=node('div','clinical-comparison');
cases.forEach((c,i)=>{const s=c.samples[0],clinical=c.clinical,card=node('article','card clinical-case'+(clinical.stenosis?' stenosis-case':''));const top=node('div','card-heading');top.append(node('h3',null,tr('case')+' '+clinical.rowId.replace('pat','')),node('span','clinical-badge'+(clinical.stenosis?' alert':''),tr(clinical.stenosis?'present':'absent')));card.append(top,node('p','finding-label',tr('finding')));if(clinical.stenosis){const anatomical=node('div','anatomical-metrics');[[tr('residual'),clinical.residualDiameterMm],[tr('reference'),clinical.referenceDiameterMm]].forEach(([label,v])=>{const box=node('div');box.append(node('span',null,label),node('strong',null,v+' mm'));anatomical.append(box);});card.append(anatomical);}else{card.append(node('div','anatomical-metrics anatomy-spacer'));}
card.append(node('p','sensor-note',tr('sensor')));
const audio=node('audio');audio.controls=true;audio.preload='metadata';audio.src='assets/research/'+s.audio;card.append(audio);
const spec=node('canvas');spec.setAttribute('aria-label',tr('freq')+' '+clinical.rowId);card.append(spec,node('p','comparison-caption',tr('fft')));drawSpectrogram(spec,s);
const features=node('div','measurement-grid');[[tr('centroid'),s.centroidHz.toFixed(1),'Hz'],[tr('dominant'),s.dominantHz.toFixed(1),'Hz'],[tr('duration'),s.duration.toFixed(1),'s']].forEach(([label,value,unit])=>{const m=node('div','measurement');m.append(node('span',null,label),node('strong',null,value),node('small',null,unit));features.append(m);});card.append(features);
const actions=node('div','detail-actions'),inspect=node('button','secondary',tr('traces'));inspect.onclick=()=>{index=i;render();document.getElementById('originalTraces').scrollIntoView({behavior:'smooth',block:'start'});};const download=node('a','text-button',tr('download'));download.href=audio.src;download.download=s.audio;actions.append(inspect,download);card.append(actions);grid.append(card);});root.append(grid,node('p','inline-note comparison-note',tr('simple')));
data=cases[index];const rawBox=node('article','card research-raw');rawBox.id='originalTraces';rawBox.append(node('h3',null,tr('raw')+' · '+data.clinical.rowId),node('p','comparison-caption',tr('rawNote')));const raw=node('canvas');raw.setAttribute('aria-label',tr('raw'));rawBox.append(raw);root.append(rawBox);drawRaw(raw);
const details=node('details','research-source');details.append(node('summary',null,tr('source')),node('p','comparison-caption',tr('processed')));const links=node('div','detail-actions');[[tr('sourceLink'),data.repository],[tr('paper'),data.paper],[tr('license'),data.license]].forEach(([label,url])=>{const a=node('a','text-button',label);a.href=url;a.target='_blank';a.rel='noopener noreferrer';links.append(a);});details.append(links,node('p','comparison-caption',data.attribution));root.append(details);}

function drawRaw(c){c.width=1200;c.height=500;const ctx=c.getContext('2d');ctx.fillStyle='#f7faf8';ctx.fillRect(0,0,1200,500);const colors=['#5295bb','#398b70','#bd9458','#8b74ab'];data.rawTraces.forEach((trace,i)=>{const top=20+i*112,bottom=top+84,range=trace.max-trace.min||1;ctx.strokeStyle='#e3eae5';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(130,bottom);ctx.lineTo(1160,bottom);ctx.stroke();ctx.fillStyle=colors[i];ctx.font='17px Arial';ctx.fillText(trace.name,12,top+30);ctx.font='12px Arial';ctx.fillText(trace.max.toFixed(3),70,top+13);ctx.fillText(trace.min.toFixed(3),70,bottom);ctx.strokeStyle=colors[i];ctx.lineWidth=1.3;trace.envelope.forEach(([lo,hi],j)=>{const x=130+j/(trace.envelope.length-1)*1030;ctx.beginPath();ctx.moveTo(x,bottom-(lo-trace.min)/range*84);ctx.lineTo(x,bottom-(hi-trace.min)/range*84);ctx.stroke();});});ctx.fillStyle='#80938a';ctx.font='15px Arial';ctx.textAlign='center';for(let i=0;i<=4;i++)ctx.fillText((10+i)+' s',130+i/4*1030,485);}
function drawSpectrogram(c,s){c.width=850;c.height=480;const ctx=c.getContext('2d'),heat=s.heatmap,h=heat.length,w=heat[0].length;ctx.fillStyle='#f7faf8';ctx.fillRect(0,0,850,480);const image=document.createElement('canvas');image.width=w;image.height=h;const ix=image.getContext('2d'),pixels=ix.createImageData(w,h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const v=heat[h-1-y][x]/255,i=(y*w+x)*4;pixels.data[i]=Math.round(10+225*v*v);pixels.data[i+1]=Math.round(35+190*Math.min(1,v*1.5));pixels.data[i+2]=Math.round(49+95*(1-v));pixels.data[i+3]=255;}ix.putImageData(pixels,0,0);ctx.imageSmoothingEnabled=false;ctx.drawImage(image,65,18,720,400);ctx.font='14px Arial';ctx.fillStyle='#698277';ctx.textAlign='right';[0,500,1000,1500].forEach(hz=>ctx.fillText(hz+' Hz',58,420-hz/1500*400));ctx.textAlign='center';[0,3,6,9,12].forEach(sec=>ctx.fillText(sec+' s',65+sec/12*720,450));ctx.fillText('relative power · −70 → 0 dB',420,475);}
new MutationObserver(()=>render()).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
Promise.all(['pat002','pat006'].map(id=>fetch('assets/research/'+id+'.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json();}))).then(c=>{cases=c;render();}).catch(()=>root.replaceChildren(node('p','empty',tr('error'))));render();})();